// Teacher head frames: tight head crops (rows 0..275, chin/neck).
// Base64 data URIs so no binary PNG has to be pushed to GitHub.
// HEAD_CLOSED is the base image head; the rest are the user-made
// variants, background-removed and aligned to the base head.
// Frame 0 = closed, 1 = slightly open, 2 = wide open, 3 = blink.
export const HEAD_CLOSED = "data:image/png;base64,";
export const HEAD_SLIGHT = "data:image/png;base64,";
export const HEAD_WIDE = "data:image/png;base64,";
export const HEAD_BLINK = "data:image/png;base64,";
export const HEAD_HAPPY = "data:image/png;base64,";
